"""Imagens do onboarding (Telas 1 e 2), recortadas da referência aprovada. Só dados: WebP em base64."""

IMAGENS = {
    "mascote": "",
    "arrojado": "",
    "equilibrado": "",
    "conservador": "",
    "iniciante": "",
    "explorador": "",
    "acoes": "",
    "fiis": "",
    "cripto": "",
    "rendafixa": "",
    "etfs": "",
    "commodities": "",
    "tecnologia": "",
    "esg": "",
    "outros": "",
    "estrela": "",
    "chapeu": "",
    "niv_iniciante": "",
    "niv_intermediario": "",
    "niv_avancado": "",
    "jornada": "",
}


def uri(nome: str) -> str:
    d = IMAGENS.get(nome)
    return f"data:image/webp;base64,{d}" if d else ""


def existe(nome: str) -> bool:
    return nome in IMAGENS
